class Notification {
    protected String recipient;
    protected String message;

    public Notification(String recipient, String message) {
        this.recipient = recipient;
        this.message = message;
    }

    public void logDispatch() {
        System.out.println("[LOG] Dispatching notification to: " + recipient);
    }
}

// Sibling Subclass 1: Email
class EmailNotification extends Notification {
    private String subject;

    public EmailNotification(String recipient, String message, String subject) {
        super(recipient, message);
        this.subject = subject;
    }

    public void sendEmail() {
        logDispatch(); // Inherited from Notification
        System.out.println("Sending EMAIL with Subject: '" + subject + "'");
        System.out.println("Body: " + message);
    }
}

// Sibling Subclass 2: SMS
class SMSNotification extends Notification {
    private int characterLimit;

    public SMSNotification(String recipient, String message, int limit) {
        super(recipient, message);
        this.characterLimit = limit;
    }

    public void sendSMS() {
        logDispatch(); // Inherited from Notification
        System.out.println("Sending SMS to " + recipient + " (Max " + characterLimit + " chars): " + message);
    }
}

public class NotificationDemo {
    public static void main(String[] args) {
        EmailNotification email = new EmailNotification("alice@example.com", "Your order has shipped!", "Shipping Update");
        SMSNotification sms = new SMSNotification("+1-555-0199", "Security Code: 492011", 160);

        System.out.println("--- 1. Email Channel ---");
        email.sendEmail();

        System.out.println("\n--- 2. SMS Channel ---");
        sms.sendSMS();

        // Sibling Isolation Demo:
        // email.sendSMS(); // COMPILE ERROR! Siblings are isolated!
    }
}

