class Account {
    String accNumber;
    double balance;

    void showBalance() {
        System.out.println(accNumber + " balance: $" + balance);
    }
}

class SavingsAccount extends Account {
    void applyBonus() {
        balance += 10.0;
        System.out.println("Bonus added! New balance: $" + balance);
    }
}

class CheckingAccount extends Account {
    void deductMaintenanceFee() {
        balance -= 5.0;
        System.out.println("Fee deducted! New balance: $" + balance);
    }
}

public class Main {
    public static void main(String[] args) {
        SavingsAccount sa = new SavingsAccount();
        sa.accNumber = "SAV-101";
        sa.balance = 500.0;
        sa.showBalance();
        sa.applyBonus();

        CheckingAccount ca = new CheckingAccount();
        ca.accNumber = "CHK-202";
        ca.balance = 200.0;
        ca.showBalance();
        ca.deductMaintenanceFee();
    }
}

