        TextBox tb = new TextBox();
        tb.widgetId = "tb-username";
        tb.render();
        tb.typeText("john_doe");
    }
}

class MediaFile {
    String fileName;
    int durationSec;

    void printMeta() {
        System.out.println(fileName + " (" + durationSec + "s)");
    }
}

class AudioFile extends MediaFile {
    int bitRateKbps;
    void playAudio() {
        System.out.println("Playing audio at " + bitRateKbps + " kbps");
    }
}

class VideoFile extends MediaFile {
    String resolution;
    void playVideo() {
        System.out.println("Streaming video in " + resolution);
    }
}

class ImageFile extends MediaFile {
    String dimensions;
    void displayImage() {
        System.out.println("Showing image at " + dimensions);
    }
}

public class Main {
    public static void main(String[] args) {
        AudioFile audio = new AudioFile();
        audio.fileName = "song.mp3";
        audio.durationSec = 210;
        audio.bitRateKbps = 320;
        audio.printMeta();
        audio.playAudio();

        VideoFile video = new VideoFile();
        video.fileName = "movie.mp4";
        video.durationSec = 7200;
        video.resolution = "1080p";
        video.printMeta();
        video.playVideo();

        ImageFile image = new ImageFile();
        image.fileName = "photo.jpg";
        image.durationSec = 0;
        image.dimensions = "1920x1080";
        image.printMeta();
        image.displayImage();
    }
}

