class CloudResource {
    protected String resourceId;
    protected String region;

    public CloudResource(String resourceId, String region) {
        this.resourceId = resourceId;
        this.region = region;
    }

    public void logProvision() {
        System.out.println("Provisioned " + resourceId + " in " + region);
    }
}

class ComputeInstance extends CloudResource {
    private int vCpuCount;

    public ComputeInstance(String id, String region, int vCpu) {
        super(id, region);
        this.vCpuCount = vCpu;
    }

    public void launch() {
        logProvision();
        System.out.println("Compute instance running with " + vCpuCount + " vCPUs.");
    }
}

class StorageBucket extends CloudResource {
    private int capacityGB;

    public StorageBucket(String id, String region, int capacity) {
        super(id, region);
        this.capacityGB = capacity;
    }

    public void mount() {
        logProvision();
        System.out.println("Storage bucket mounted with " + capacityGB + " GB storage.");
    }
}

public class Main {
    public static void main(String[] args) {
        ComputeInstance vm = new ComputeInstance("vm-prod-01", "us-east-1", 8);
        vm.launch();

        StorageBucket bucket = new StorageBucket("s3-logs-bucket", "us-west-2", 500);
        bucket.mount();
    }
}
